{"jsonrpc":"2.0","id":56,"method":"tools/call","params":{"name":"mandate.apply_patch","arguments":{"source":"// Acme design task class 3 (design doc 9 §10.3; BACKLOG item 33): a
// change to the token audience acme-mcp accepts. A planner proposes, the
// architect accepts the plan, an agent changes acme-mcp, and the runtime
// checks the change at the boundary before anything lands:
//
//   suites      acme-mcp's own tests, pinned to the base commit
//   contracts   no interface changes, as the plan says
//   integrated  the whole system, built from the candidate, end to end on
//               staging data, on a network with no way out
//   planned     nothing outside the accepted plan changed: no other component,
//               no interface the plan does not name
//
// A change that moves only one side of the audience agreement passes the
// first two and is caught by the third.

mandate @ 0.3

module acme.tasks.audience @ 0.1

use std.{component, model, test, git, human}
use acme.system.{mcp, staging}

capability McpRead  = component.read(mcp)
capability McpSrc   = component.write(mcp, "src", "test")
capability McpTest  = component.exec(mcp, test)
capability McpRepo  = component.repo(mcp)
capability ModelStd = model.infer(tier: standard)

type Task = { id: Text, request: Text }
type Plan = { summary: Text, components: List<Text>, changes: Map<Text, Text> }
type Change = { files: List<Text>, summary: Text }

contract PlanAccepted(plan: Plan) {
  accept architect "The architect accepted the plan" by human.approve(role: "architect")
}

contract BoundaryAccepted(change: Change, plan: Plan) {
  accept suites "Each component the plan changes passes its own tests" by test.suite_each(plan.components)
  accept contracts "Interfaces change only as the plan declares" by test.contract(plan.changes)
  accept integrated "The system works end to end on staging data" by test.integration(env: staging, plan.components)
  accept planned "Nothing outside the accepted plan changed" by test.planned(plan)
}

agent Planner {
  role   "Turns a request into a plan: which components change, and how each interface changes."
  caps   McpRead, ModelStd
  budget { tokens: 400k, spend: 2 USD, steps: 6 }
  skill plan(task: Task) -> Inferred<Plan> ! {Fs.Read, Model}
}

agent McpDev {
  role   "Changes acme-mcp as the accepted plan says, with its tests."
  caps   McpRead, McpSrc, McpTest, ModelStd
  budget { tokens: 800k, time: 20m, spend: 4 USD, steps: 12 }
  skill implement(plan: Verified<Plan, PlanAccepted>) -> Inferred<Change> ! {Fs.Read, Fs.Write, Exec, Model}
}

workflow Audience(task: Task) -> Text
  caps    McpRead, McpSrc, McpTest, McpRepo, ModelStd
  budget  { spend: 8 USD, time: 1h }
{
  let draft = delegate Planner.plan(task)
  let plan = verify draft against PlanAccepted(draft)
  let change = delegate McpDev.implement(plan)
  let checked = verify change against BoundaryAccepted(change, plan)
    on unmet(c) => escalate human("Open acceptance criteria: {c}")
  let landed = changeset(plan) {
    member mcp = git.merge(checked)
    order mcp
    approve role "architect"
  } idempotent_by task.id
  "landed"
}
","base":"sha256:5906789ba25f7889053a05a9279a24511312a19836af4b89e926ceccfed35e89","ops":[{"op":"replace","path":"/version","value":"0.2"}],"modules":["// A system model test fixture (design doc 9 §2): Acme, a fictional delivery
// company of six components.
// The components, the interfaces between them and the environments they run
// in, as a Mandate module. Programs import what they work on:
//
//   use acme.system.{mcp, core, CoreApi, prod_sim}
//
// The lock file pins this module by its hash, so a run's system model never
// changes under it. Changing anything here is a governance change.

mandate @ 0.3

module acme.system @ 0.1

// ── Interfaces ─────────────────────────────────────────────────────────────
interface TokenIssuance {
  protocol oauth
  spec     "docs/oauth-metadata.json"
}

interface CustomerTools {
  protocol mcp_tools
  spec     "docs/mcp-tools.json"
}

interface CoreApi {
  protocol openapi
  spec     "docs/openapi.json"
}

interface CoreSchema {
  protocol db_schema
  spec     "src/main/resources/db/migration"
}

interface SearchApi {
  protocol openapi
  spec     "docs/openapi.json"
}

interface AgentApi {
  protocol openapi
  spec     "docs/openapi.json"
}

// ── Components ────────────────────────────────────────────────────────────
component auth {
  repo     "acme/auth"
  root     "/work/acme-auth"
  lang     ts
  owner    role "identity_owner"
  build    exec("npm", ["ci", "--ignore-scripts"]), exec("npm", ["run", "build"])
  test     exec("npm", ["test"])
  provides TokenIssuance
}

component mcp {
  repo     "acme/mcp"
  root     "/work/acme-mcp"
  lang     ts
  owner    role "support_platform_owner"
  build    exec("npm", ["ci", "--ignore-scripts"]), exec("npm", ["run", "build"])
  test     exec("npm", ["test"])
  provides CustomerTools
  consumes CoreApi, SearchApi, TokenIssuance
}

component core {
  repo     "acme/core"
  root     "/work/acme-core"
  lang     java
  owner    role "core_owner"
  build    exec("mvn", ["-B", "-q", "-o", "-DskipTests", "package"])
  test     exec("mvn", ["-B", "-q", "-o", "test"])
  provides CoreApi, CoreSchema
  // Beyond the language's governance-class files (K70): core's deploy scripts.
  governance "deploy/**"
}

component search {
  repo     "acme/search"
  root     "/work/acme-search"
  lang     py
  owner    role "search_owner"
  test     exec("python", ["-m", "pytest", "-q"])
  provides SearchApi
}

component voice {
  repo     "acme/voice"
  root     "/work/acme-voice"
  lang     ts
  owner    role "agent_owner"
  build    exec("npm", ["ci", "--ignore-scripts"]), exec("npm", ["run", "build"])
  test     exec("npm", ["test"])
  provides AgentApi
  consumes CustomerTools, TokenIssuance
}

component evals {
  repo     "acme/voice-evals"
  root     "/work/acme-voice-evals"
  lang     py
  owner    role "agent_owner"
  test     exec("python", ["-m", "pytest", "-q"])
  consumes AgentApi
}

// ── Data the environments hold ────────────────────────────────────────────
type CustomerName = Text classified confidential
type Phone = Text classified confidential
type Email = Text classified confidential

// One row of v_shipment_overview: shipment, delivery and its customer.
type ShipmentRow = {
  tracking_no: Text, status: Text, destination_city: Text, delivery_date: Text,
  delivery_status: Text, attempts: Int, full_name: CustomerName, phone: Phone, email: Email
}

// The same without the customer: what a lower environment may hold.
type ShipmentStatusRow = { tracking_no: Text, status: Text, destination_city: Text, delivery_date: Text, delivery_status: Text, attempts: Int }

type TicketRow = { ticket_id: Text, tracking_no: Text, category: Text, status: Text, channel: Text, created_at: Text }

type EventRow = { tracking_no: Text, at: Text, description: Text }

// One log line. Logs hold no personal data.
type LogLine = { ts: Text, level: Text, service: Text, msg: Text, tool: Text, status: Int, trace_id: Text }

// ── Environments (doc 9 §10.2) ─────────────────────────────────────────────
environment dev {
  class internal
  read shipment_status from core
    sql "select tracking_no, status, destination_city, delivery_date, delivery_status, attempts from v_shipment_overview where tracking_no = :tracking_no"
    params (tracking_no: Text)
    returns ShipmentStatusRow
    max_rows 1
}

environment staging {
  class internal
  read shipment_status from core
    sql "select tracking_no, status, destination_city, delivery_date, delivery_status, attempts from v_shipment_overview where tracking_no = :tracking_no"
    params (tracking_no: Text)
    returns ShipmentStatusRow
    max_rows 1
  authorize deploy by policy
  authorize migrate by policy
}

// The "production" of Acme: confidential synthetic customer data, read only
// through the read broker, written only through the CD adapter.
environment prod_sim {
  class confidential
  read shipment_overview from core
    sql "select tracking_no, status, destination_city, delivery_date, delivery_status, attempts, full_name, phone, email from v_shipment_overview where tracking_no = :tracking_no"
    params (tracking_no: Text)
    returns ShipmentRow
    max_rows 1
  read shipment_events from core
    sql "select tracking_no, at, description from shipment_events where tracking_no = :tracking_no order by at"
    params (tracking_no: Text)
    returns EventRow
    max_rows 200
  read tickets_since from core
    sql "select ticket_id, tracking_no, category, status, channel, created_at from tickets where created_at >= cast(:since as timestamptz) order by created_at desc"
    params (since: Text)
    returns TicketRow
    max_rows 500
  read mcp_errors from mcp
    logs where (level == "error" or level == "warn") and ts >= since
    params (since: Text)
    returns LogLine
    max_rows 500
  read core_warnings from core
    logs where (level == "warn" or level == "error") and ts >= since
    params (since: Text)
    returns LogLine
    max_rows 500
  authorize deploy by human(role: "release_manager")
  authorize migrate by human(role: "db_owner")
}
